// FROZEN ORACLE — the Node implementation of src/chat/auto-provider-selection-key.js
// as it stood when the auto-provider modules were frozen for the Rust port
// (frozen 2026-11-11). Byte-for-byte the same source with only the require
// path adapted: it still calls the real (retained) config bridge, because that
// module is not part of this migration.
//
// Do not edit this file. Only a confirmed behaviour change may re-record the
// fixtures (scripts/generate-auto-provider-fixtures.js --write), and that
// re-record must first explain the change in the same commit.

const { normalizeStoredProviderSelection } = require('../../src/providers/auto-provider-config');

// Session records are cloned during a CLI handoff and persistence hydration.
// Only a policy change, not a new object holding the same policy, resets its
// current route. Normalization fixes key order and resolves omitted defaults.
function selectionKey(selection) {
  const normalized = normalizeStoredProviderSelection(selection);
  if (!normalized) return null;
  // presetId is a display label ("this pool came from preset X"), not routing
  // policy: saving the same pool again under another preset must not reset the
  // session's sticky route or its notes.
  const policy = { ...normalized };
  delete policy.presetId;
  return JSON.stringify(policy);
}

module.exports = { selectionKey };
